from dataclasses import dataclass


@dataclass
class Rect:
    w: int
    h: int


@dataclass
class Square:
    side: int


@dataclass
class Tri:
    b: int
    h: int


Shape = Rect | Square | Tri


def area(s: Shape) -> int:
    """Area of the shape, rounded down to an int.

    Rect is w*h, Square is side*side, Tri is b*h/2 (floored).
    """
    match s:
        case Rect(w=w, h=h):
            return w * h
        case Square(side=side):
            return side * side
        case Tri(b=b, h=h):
            return (b * h) // 2


def test_rect() -> None:
    assert area(Rect(3, 4)) == 12
    assert area(Rect(0, 5)) == 0


def test_square() -> None:
    assert area(Square(5)) == 25
    assert area(Square(0)) == 0


def test_tri_even() -> None:
    assert area(Tri(4, 3)) == 6


def test_tri_rounds_down() -> None:
    assert area(Tri(3, 3)) == 4
    assert area(Tri(1, 1)) == 0


def test_tri_zero() -> None:
    assert area(Tri(0, 7)) == 0


def test_large_values_exact() -> None:
    big = 10**12 + 1
    assert area(Tri(big, big)) == (big * big) // 2
    assert area(Rect(big, 2)) == 2 * big

